using System.Data.Common;
using System.Text;
using Dapper;

namespace HowlDev.IO.OOSql;

/// <summary>
/// Holds functions/parameters to get completed queries. 
/// </summary>
/// <typeparam name="T">ISqlTable</typeparam>
/// <typeparam name="D">IBaseDTO</typeparam>
public class CompleteQuery<T, D> where T : ISqlTable where D : IBaseDTO {
    /// <summary>
    /// Inspect the SQL generated by the query.
    /// </summary>
    public string Sql {
        get {
            StringBuilder builder = new();
            builder.Append("select");
            D obj = Activator.CreateInstance<D>();
            foreach (var item in obj.Properties) {
                builder.Append($" {item.name} ");
            }
            builder.Append("from ");
            builder.Append(typeof(T).Name[..^5]);
            return builder.ToString();
        }
    }

    public D QuerySingle(DbConnection conn) {
        return conn.QuerySingle<D>(Sql);
    }
}
